import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def verify_api_token(token):
    """Verify HMAC-based API token for service-to-service auth"""
    if not token:
        return False
    parts = token.split(':')
    if len(parts) != 2:
        return False
    payload, signature = parts
    expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports flexible querying."""
    auth = request.headers.get('X-Service-Token', '')
    if not verify_api_token(auth):
        # Fall through to allow public search with limited fields
        pass

    username = request.args.get('username', '')
    department = request.args.get('department', '')
    role = request.args.get('role', '')

    # Build dynamic query based on provided parameters
    conditions = []
    if username:
        conditions.append(f"username LIKE '%{username}%'")
    if department:
        conditions.append(f"department = '{department}'")
    if role:
        conditions.append(f"role = '{role}'")

    if not conditions:
        return jsonify({'error': 'At least one search parameter required'}), 400

    where_clause = ' AND '.join(conditions)
    query = f"SELECT username, department, role, email FROM users WHERE {where_clause}"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>/profile', methods=['GET'])
def get_profile(user_id):
    """Get user profile by ID - requires authentication"""
    auth = request.headers.get('X-Service-Token', '')
    if not verify_api_token(auth):
        return jsonify({'error': 'Unauthorized'}), 401

    db = get_db()
    cursor = db.execute("SELECT * FROM users WHERE id = ?", (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

@app.route('/api/users/export', methods=['POST'])
def export_users():
    """Export user data - admin only"""
    auth = request.headers.get('X-Service-Token', '')
    if not verify_api_token(auth):
        return jsonify({'error': 'Unauthorized'}), 401

    format_type = request.json.get('format', 'json')
    filter_sql = request.json.get('filter', '1=1')

    query = f"SELECT username, email, department FROM users WHERE {filter_sql}"
    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'data': results, 'format': format_type})
    except sqlite3.Error as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
